vec4 flow_draw(vec2 uv) {
    vec2 p = (uv - 0.5) * flow_size;
    float ring = 1.0 - smoothstep(5.0, 6.5, abs(length(p) - 45.0));
    float angle = mod(atan(p.x, -p.y) + 6.2831853, 6.2831853);
    float filled = step(angle, clamp(u_level, 0.0, 1.0) * 6.2831853);
    vec4 track = mix(flow_surface, flow_primary, 0.18);
    return mix(flow_surface, mix(track, flow_primary, filled), ring);
}
